<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';import {apiError} from './apiError';
const props=defineProps<{projectId:string;focusId?:string}>();const jobs=ref<any[]>([]),selected=ref<any>(null),error=ref('');let generation=0,timer:ReturnType<typeof setTimeout>|undefined;
const terminal=new Set(['succeeded','incomplete','failed','cancelled','interrupted']);const names:Record<string,string>={queued:'排队',running:'计算中',cancel_requested:'等待取消',succeeded:'计算完成',incomplete:'结果不完整',failed:'失败',cancelled:'已取消',interrupted:'中断'};
async function api(path:string,method='GET'){const r=await fetch('/api/study-jobs'+path,{method});const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
async function refresh(){const g=generation;clearTimeout(timer);if(!props.projectId)return;try{const h=await api('?project_id='+props.projectId);if(g!==generation)return;jobs.value=h;if(selected.value){const d=await api('/'+selected.value.id+'?include_input=true&include_result=true');if(g===generation)selected.value=d}if(g===generation&&h.some((j:any)=>!terminal.has(j.status)))timer=setTimeout(refresh,1500)}catch(e){if(g===generation){error.value=String(e);timer=setTimeout(refresh,4000)}}}
async function inspect(id:string){const g=generation;try{const d=await api('/'+id+'?include_input=true&include_result=true');if(g===generation&&d.project_id===props.projectId)selected.value=d}catch(e){if(g===generation)error.value=String(e)}}
async function action(id:string,type:string){const g=generation;try{const d=await api('/'+id+'/'+type,'POST');if(g!==generation)return;selected.value=d;await refresh()}catch(e){if(g===generation)error.value=String(e)}}
watch(()=>[props.projectId,props.focusId],async()=>{++generation;selected.value=null;jobs.value=[];error.value='';await refresh();if(props.focusId)await inspect(props.focusId)},{immediate:true});onBeforeUnmount(()=>{++generation;clearTimeout(timer)});
</script>
<template><article><h3>计算任务 · 调度、年度滚动、承灾、恢复、源储配置及方案比较</h3><p>本入口管理上述六类后台任务；原生年度流水线仍在独立入口。最多2个任务同时运行，重试创建新档案并保留原工程、台账及网络快照；联合配置和方案比较可停止独占原生求解子进程；其余四类取消在当前有界MILP结束后生效。</p><p v-if="error" class="error">{{error}}</p><button @click="refresh">刷新任务</button><div class="scroll"><table><tr><th>名称/模块</th><th>状态</th><th>进度</th><th>创建时间</th><th>操作</th></tr><tr v-for="j in jobs" :key="j.id"><td>{{j.name}}<br>{{j.module}}</td><td>{{names[j.status]||j.status}}</td><td>{{((j.progress?.fraction||0)*100).toFixed(1)}}% · {{j.progress?.phase}}</td><td>{{new Date(j.created*1000).toLocaleString()}}</td><td><button @click="inspect(j.id)">查看</button> <button v-if="!terminal.has(j.status)" @click="action(j.id,'cancel')" :disabled="j.status==='cancel_requested'">取消</button><button v-else @click="action(j.id,'retry')">冻结输入重试</button></td></tr></table></div><p v-if="!jobs.length">本工程尚无统一研究任务。</p></article>
<article v-if="selected"><h3>{{selected.name}} · {{names[selected.status]}}</h3><p>{{selected.id}} · {{selected.input_sha256}}</p><p class="error" v-if="selected.error">{{selected.error}}</p><div class="actions"><a :href="'/api/study-jobs/'+selected.id+'/download'">{{selected.module==='investment_experiments'?'研究快照与汇总 JSON':'完整快照与结果 JSON'}}</a><a v-if="selected.result" :href="'/api/study-jobs/'+selected.id+'/csv'">结果 CSV</a><a :href="'/api/study-jobs/'+selected.id+'/log'" target="_blank">工作日志</a></div>
<template v-if="selected.module==='device_dispatch'&&selected.result?.metrics"><h4>逐设备调度结果</h4><p>未供电量 {{selected.result.metrics.total_unsupplied_energy_kwh.toFixed(3)}} kWh · 最大缺额 {{selected.result.metrics.maximum_total_unsupplied_kw.toFixed(3)}} kW · 求解状态 {{selected.result.status}}</p><div class="scroll"><table><tr><th>时间</th><th>负荷 kW</th><th>供电 kW</th><th>未供 kW</th><th>电网 kW</th></tr><tr v-for="r in selected.result.rows"><td>{{r.timestamp}}</td><td>{{r.load_kw.toFixed(3)}}</td><td>{{r.served_kw.toFixed(3)}}</td><td>{{r.total_unsupplied_kw.toFixed(3)}}</td><td>{{r.grid_kw.toFixed(3)}}</td></tr></table></div><p v-for="s in selected.result.scope">{{s}}</p></template>
<p v-if="selected.module==='annual_dispatch'&&selected.result">年度滚动覆盖 {{selected.result.coverage.completed_steps}} / {{selected.result.coverage.requested_steps}} 步。已提交轨迹和窗口证据见“电力电量平衡 → 逐设备年度滚动”。</p>
<p v-if="selected.module==='disaster_scan'&&selected.result?.cases">承灾扫描完成 {{selected.result.completed_solves}} / {{selected.result.requested_solves}} 次；边界与薄弱设备表请在“承灾极限分析”中打开该档案。</p>
<p v-if="selected.result?.actions">恢复规划：{{selected.result.actions.length}}步操作 / {{selected.result.partitions.length}}个带电分区。恢复状态{{selected.result.goal_status}}；未获动态安全执行许可，详细回放请在“黑启动路径优化”打开本档案。</p><p v-if="selected.module==='investment'&&selected.result">源储配置：{{selected.result.status}} · 折现成本{{selected.result.objective_yuan??'未获可行解'}}元。选址、投运年、机会约束及现金流请在“源储协同配置”打开档案。</p><p v-if="selected.module==='investment_experiments'&&selected.result">配置比较：{{selected.result.status}}，{{selected.result.cases.length}}个算例；有限扫描与敏感性详细结果见源储配置，完整单例证据分别归档。</p><details><summary>输入版本与参数</summary><pre>{{JSON.stringify(selected.input,null,2)}}</pre></details></article></template>
<style scoped>.scroll{overflow:auto;max-height:420px;margin:15px 0}.actions{display:flex;gap:20px;flex-wrap:wrap;margin:20px 0}pre{max-height:400px;overflow:auto}td,th{white-space:nowrap}</style>
